package com.optarena.app

object Parser {
    // Parse the integers out of the tokens, in order, skipping invalid ones.
    // BUG: toInt() throws on the first non-numeric token instead of skipping.
    fun parseInts(tokens: List<String>): List<Int> {
        return tokens.map { it.trim().toInt() }
    }
}

