package com.optarena.app

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Test

class ParserTest {

    @Test
    fun parsesValidIntegers() {
        assertEquals(listOf(1, 2, 3), Parser.parseInts(listOf("1", " 2 ", "3")))
    }

    @Test
    fun skipsInvalidTokens() {
        assertEquals(listOf(1, 3), Parser.parseInts(listOf("1", "x", "3", "")))
    }

    @Test
    fun allInvalidIsEmpty() {
        assertEquals(emptyList<Int>(), Parser.parseInts(listOf("a", "b", "--")))
    }
}

