package com.optarena.app

object Parser {
    // Stops throwing but substitutes 0 for invalid tokens instead of skipping.
    fun parseInts(tokens: List<String>): List<Int> {
        return tokens.map { it.trim().toIntOrNull() ?: 0 }
    }
}
